"""从菜单文档生成页面设计总表；保持60个入口可追溯。"""
from pathlib import Path
import re
root=Path(__file__).resolve().parents[2] / "docs/eam"
rows=[]
for line in (root/'2026-10-10-功能菜单设计.md').read_text(encoding='utf-8').splitlines():
    if re.match(r'^\| [WEIMCSOARTDX]\d{2} \|',line):
        cells=[x.strip() for x in line.strip('|').split('|')]
        rows.append(cells)
assert len(rows)==60 and len({r[0] for r in rows})==60
families={'W':'工作台/队列','E':'台账/树/变更','I':'标准计划/任务执行/结果','M':'发现/问题/工单/维护/履约','C':'计量/检验','S':'备件/来源单据','O':'监控/事件/趋势','A':'指标/报表','R':'风险/措施/改善','T':'版本配置/发布','D':'履历/证据/审核','X':'配置/集成/重算'}
prototype={'R04':'hazards','E06':'functional-locations','T01':'equipment-templates','W01':'workbench','E01':'equipment','M07':'abnormal-events','M08':'failure-events','M01':'defect-list','M02':'order-list','I02':'inspection-list','I01':'plan-list','T02':'standard-list','E02':'equipment','E03':'equipment','I03':'inspection-list','D03':'history'}
out=['# EAM 页面设计总表','', '维护业务最新设计见[对象流程基线](../业务设计/维护业务对象流程与关闭规则基线.md)及[页面验收矩阵](../业务设计/维护业务页面模型候选数据与验收矩阵.md)，旧验收联动关闭不是新目标。', '', '模型期新规则：每页登记候选表/字段和接口，见[逐页索引](页面记录/首批页面候选数据与接口索引.md)；全部模型完成后统一正式数据库/API设计。', '', '当前操作基线见[首批页面操作矩阵](2026-10-10-首批页面操作矩阵与交互验收.md)，新增字段关系见[维护补充](../数据设计/首批维护字段与数据关系补充.md)。本表菜单概要不替代逐页操作矩阵。', '', '日期：2026-10-10。全量60项菜单映射；第一批仅实现核心闭环HTML。页面族复用模板，不等于复用业务对象。', '', '## 1. 全量页面目录','', '| 菜单 | 名称 | 路由 | 页面族 | 内容/字段与操作范围 | 角色 | 原型状态 |','| --- | --- | --- | --- | --- | --- | --- |']
for r in rows:
    status=f'首批场景切片 / [{prototype[r[0]]}.html](../prototype/pages/{prototype[r[0]]}.html)；首批优化已实现，专业扩展待设计' if r[0] in prototype else '菜单/页面范围概要；详细字段模型与高保真待设计'
    if r[0] in {'M02','R04'}: status += '；工单逐问题验收/独立业务关闭与隐患协同JSON接口已实现'
    if r[0] in {'M01','M07','M08'}: status += '；独立问题JSON接口本批实现，工单与隐患协同本批改造，档案实时聚合待迁移'
    out.append(f'| {r[0]} | {r[1]} | {r[2]} | {families[r[0][0]]} | {r[3]} | {r[4]} | {status} |')
out+=['','## 2. 所有页面必须设计的状态','','列表：加载、正常、空数据、无权限、读取失败、分页/筛选。表单：草稿、校验失败、提交中、提交失败、并发冲突、成功、只读历史。流程：待处理、执行、阻断、暂停、退回、取消、关闭，按业务合法转换。统计：数据不足、未知状态、口径与单位、无数据非零值。','', '后续批次高保真需按此状态清单逐页展开；本批实际HTML仅演示空数据、无模块权限、陈旧信号、必填失败、越权、验收退回及关闭。加载/服务失败/并发冲突已提供情境模拟；非真实网络故障验证。','','## 3. 第一批历史页面模型（维护业务以新基线覆盖）','','| 页面 | 字段/区块 | 操作与跳转 | 逻辑对象 |','| --- | --- | --- | --- |','| 平台演示外壳 | 平台模块卡片、模拟角色控件 | 设备管理→角色工作台；原平台样式待对接 | 平台身份/上下文 |','| 角色工作台 | 角色标题、范围、指标、任务、快捷入口 | 指标与待办到业务列表/详情；13角色可切换 | 工作台投影 |','| 设备台账/详情 | 编码、名称、型号、责任、位置、独立状态 | 新增、查看、编辑、草稿删除、生命周期、结构/附件维护、筛选分页与全景 | equipment/state |','| 点检执行 | 任务、标准快照、温度、润滑、防护、单位、异常描述和证据 | 草稿、必填校验、异常产生待分诊报告 | inspection_task/result |','| 缺陷报修 | 描述、来源、等级、关联工单 | 报修→受理派工，禁止重复生成工单 | defect |','| 维修执行 | 指派人、安全确认、过程、试运行 | 开工→完工；退回后重新执行 | work_order/execution |','| 验收 | 执行人、执行版本、恢复/试运行/缺陷消除确认、验收意见 | 退回返工/验收关闭；职责分离 | acceptance |','| 设备履历 | 事件、责任人、时间、关联对象 | 关联过程查看；历史只读 | audit_event/projection |','','## 4. 本批范围与边界','','移动端采用模块内标签，不替换平台导航；每个业务页面为独立HTML，公共样式按视口适配，pc/mobile入口只是视口预设。角色切换和情境下拉仅是评审控件。未实现模块显示目录说明。会话模拟数据可重置，不执行真实领料、扫码、上传、审批或数据库写入。']
out += ['', '## 5. 首批审查状态', '', '上表内容/字段与操作范围是目标设计，不代表HTML已实现。25个独立HTML包含23个业务/子页、平台外壳与评审目录，覆盖16个菜单的部分场景；其余44菜单只有概要。13角色标签可切换，13角色均有不同摘要和入口；专业队列完整业务仍待后续批次。逐页缺口见[历史字段审查](2026-10-10-首批字段与文档审查.md)，数据来源见[字段字典](../数据设计/首批数据结构字典.md)，当前进度见[进度入口](../设计与原型进度.md)。']
(root/'页面设计/页面设计总表.md').write_text('\n'.join(out)+'\n',encoding='utf-8')
print(f'Generated page catalog: {len(rows)} menu entries')

